/* ==================================================================
   MATCHING HELPERS
================================================================== */
const normaliseKey = (s) =>
  (s || "")
    .toString()
    .trim()
    .toLowerCase()
    .replace(/&/g, "and")
    .replace(/[^a-z0-9]/g, "");

const FAQ_LOOKUP = Object.keys(COURSE_FAQS).reduce((acc, key) => {
  acc[normaliseKey(key)] = COURSE_FAQS[key];
  return acc;
}, {});

